function AutoChessMode.prototype.handleBattleCompleted(self, data)
    local battleId = data.battleId or (("battle_" .. tostring(data.player1)) .. "_") .. tostring(Date:now())
    local player1 = data.player1
    local player2 = data.player2 or -1
    local winnerId = data.winnerId
    local battleKey = (tostring(player1) .. "_vs_") .. tostring(player2)
    local playerWon = winnerId == player1
    local winner = playerWon and "player" or "enemy"
    print("[AutoChessMode] ========== handleBattleCompleted CALLED ==========")
    print((("[AutoChessMode] battleId: " .. tostring(battleId)) .. ", battleKey: ") .. battleKey)
    print((((("[AutoChessMode] player1: " .. tostring(player1)) .. ", player2: ") .. tostring(player2)) .. ", winnerId: ") .. tostring(winnerId))
    print((("[AutoChessMode] playerWon: " .. tostring(playerWon)) .. ", winner: ") .. winner)
    print((("[AutoChessMode] isActive: " .. tostring(self.isActive)) .. ", currentPhase: ") .. self.gameState.currentPhase)
    if self.gameState.currentPhase ~= ____exports.RoundPhase.BATTLE then
        print("[AutoChessMode] Not in battle phase, triggering settlement directly (单机模式)")
        local currentNodeId = self.currentWaveStageSelection or "L1_1"
        local isEvent = StageConfigManager:isEventNode(currentNodeId)
        local isFirstStage = currentNodeId == "L1_1"
        print("[AutoChessMode] 🔍 单机模式 - Checking augment conditions:")
        print("[AutoChessMode]   - currentNodeId: " .. currentNodeId)
        print("[AutoChessMode]   - isEvent: " .. tostring(isEvent))
        print("[AutoChessMode]   - isFirstStage: " .. tostring(isFirstStage))
        print("[AutoChessMode]   - playerWon: " .. tostring(playerWon))
        local augmentOptions = {}
        if (isEvent or isFirstStage) and playerWon then
            print("[AutoChessMode] ✅ 单机模式 - Conditions met! Generating augment options...")
            local excludeIds = self.augmentManager:getPlayerAugments(player1)
            local options = HextechAugmentConfig:getRandomAugments(excludeIds, 3)
            augmentOptions = __TS__ArrayMap(
                options,
                function(____, aug) return {
                    id = aug.id,
                    displayName = aug.displayName,
                    description = aug.description,
                    icon = aug.icon,
                    rarity = aug.rarity
                } end
            )
            print(("[AutoChessMode] 🎲 单机模式 - Generated " .. tostring(#augmentOptions)) .. " augment options:")
            for ____, opt in ipairs(augmentOptions) do
                print(((("[AutoChessMode]   - " .. tostring(opt.displayName)) .. " (") .. tostring(opt.id)) .. ")")
            end
        else
            print("[AutoChessMode] ❌ 单机模式 - Conditions NOT met for augment generation")
        end
        local settlementData = {
            round = self.gameState.currentRound or 1,
            winner = winner,
            rewardGold = 0,
            availableStages = {},
            playerSummary = {},
            stats = {},
            levelName = nil,
            isGameOver = not playerWon,
            isEventNode = isEvent or isFirstStage,
            augmentOptions = augmentOptions
        }
        print("[AutoChessMode] 📦 单机模式 - Settlement data prepared:")
        print("[AutoChessMode]   - isEventNode: " .. tostring(settlementData.isEventNode))
        print("[AutoChessMode]   - augmentOptions count: " .. tostring(#settlementData.augmentOptions))
        print(((((("[AutoChessMode] 📤 Sending settlement to player " .. tostring(player1)) .. " (winner: ") .. winner) .. ", gameOver: ") .. tostring(not playerWon)) .. ")")
        local player = PlayerResource:GetPlayer(player1)
        if player then
            CustomGameEventManager:Send_ServerToPlayer(player, "autochess_wave_settlement", settlementData)
            print("[AutoChessMode] ✅ Settlement event sent to player " .. tostring(player1))
        end
        return
    end
    if self.battleResultsProcessed:has(battleKey) then
        print(("[AutoChessMode] Battle " .. battleKey) .. " already processed, ignoring")
        return
    end
    self.battleResultsProcessed:add(battleKey)
    local playerId = player1
    local playerState = self.gameState.playerStates:get(playerId)
    if playerState then
        if playerWon then
            playerState.winStreak = playerState.winStreak + 1
            playerState.lossStreak = 0
            print(((("[AutoChessMode] Player " .. tostring(playerId)) .. " won the battle! (winStreak: ") .. tostring(playerState.winStreak)) .. ")")
            local currentSelection = self.currentWaveStageSelection or "L1_1"
            print("[AutoChessMode] 🔍 检查关卡解锁: currentWaveStageSelection = " .. currentSelection)
            print("[AutoChessMode] ✅ 将解锁关卡: " .. currentSelection)
            self:unlockNextStages(currentSelection)
        else
            playerState.lossStreak = playerState.lossStreak + 1
            playerState.winStreak = 0
            playerState.isAlive = false
            print(("[AutoChessMode] Player " .. tostring(playerId)) .. " lost all pieces! Game over for this player.")
        end
    end
    local allBattlesCompleted = self:checkAllBattlesCompleted()
    if allBattlesCompleted then
        print("[AutoChessMode] All battles completed, ending battle phase")
        self:endBattlePhase()
    else
        print("[AutoChessMode] Waiting for other battles to complete...")
    end
    print("[AutoChessMode] ========== handleBattleCompleted COMPLETE ==========")
end
function AutoChessMode.prototype.checkAllBattlesCompleted(self)
    local activeBattles = self.battleSystem:getActiveBattles()
    local alivePlayers = #__TS__ArrayFilter(
        __TS__ArrayFrom(self.gameState.playerStates:values()),
        function(____, state) return state.isAlive end
    )
    if alivePlayers == 0 then
        return true
    end
    for ____, battle in ipairs(activeBattles) do
        if not battle.completed then
            return false
        end
    end
    return true
end
