function AutoChessMode.prototype.initializeAutoChessMode(self)
    print("[AutoChessMode] ========== 初始化自走棋模式 ==========")
    ListenToGameEvent(
        "game_rules_state_change",
        function()
            self:onGameStateChanged()
        end,
        self
    )
    print("[AutoChessMode] ✅ 游戏状态事件监听已注册")
    local currentState = GameRules:State_Get()
    print("[AutoChessMode] 当前游戏状态: " .. tostring(currentState))
    if currentState >= 5 then
        print("[AutoChessMode] 游戏已在进行中，立即尝试激活...")
        Timers:CreateTimer(
            1,
            function()
                if not self.isActive then
                    print("[AutoChessMode] 延迟激活自走棋模式...")
                    self:onPreGame()
                end
                return nil
            end
        )
