function AutoChessMode.prototype.onGameStateChanged(self)
    local gameState = GameRules:State_Get()
    local stateNames = {
        "INIT",
        "WAIT_FOR_PLAYERS_TO_LOAD",
        "CUSTOM_GAME_SETUP",
        "HERO_SELECTION",
        "STRATEGY_TIME",
        "PRE_GAME",
        "GAME_IN_PROGRESS",
        "POST_GAME",
        "DISCONNECT",
        "TEAM_SHOWCASE",
        "CUSTOM_GAME_SETUP_2",
        "WAIT_FOR_MAP_TO_LOAD"
    }
    local stateName = stateNames[gameState + 1] or "UNKNOWN_" .. tostring(gameState)
    print(((("[AutoChessMode] ========== 游戏状态变化: " .. tostring(gameState)) .. " (") .. stateName) .. ") ==========")
    print("[AutoChessMode] 当前 isActive 状态: " .. tostring(self.isActive))
    print("[AutoChessMode] 当前 isGameActive 状态: " .. tostring(self.gameState.isGameActive))
    if gameState == 5 or gameState == 10 then
        print("[AutoChessMode] ✅ 检测到目标状态 " .. stateName)
        if not self.isActive then
            print(("[AutoChessMode] 📍 " .. stateName) .. " 阶段 - 准备激活自走棋")
            self:onPreGame()
        else
            print("[AutoChessMode] ⚠️ 自走棋已激活，跳过重复激活")
        end
    end
    if gameState == 6 and stateName == "GAME_IN_PROGRESS" then
        if self.isActive and not self.gameState.isGameActive then
            print("[AutoChessMode] 📍 GAME_IN_PROGRESS 阶段 - 游戏开始")
            self:onGameStart()
        end
    end
end
function AutoChessMode.prototype.onPreGame(self)
    local gameModeManager = GameModeManager:getInstance()
    local currentMode = gameModeManager:getCurrentMode()
    print("[AutoChessMode] onPreGame called, current mode: " .. currentMode)
    print("[AutoChessMode] isAutoChessMode: " .. tostring(gameModeManager:isAutoChessMode()))
    if not gameModeManager:isAutoChessMode() then
        print("[AutoChessMode] ⚠️ 不是自走棋模式，但仍然激活以支持战斗系统")
    end
    print("[AutoChessMode] ✅ 激活自走棋模式...")
    self:activate()
    print("[AutoChessMode] 📍 将在2秒后开始游戏...")
    Timers:CreateTimer(
        2,
        function()
            print((("[AutoChessMode] 定时器触发: isActive=" .. tostring(self.isActive)) .. ", isGameActive=") .. tostring(self.gameState.isGameActive))
            if self.isActive and not self.gameState.isGameActive then
                print("[AutoChessMode] ✅ 定时器: 自动开始游戏...")
                self:startGame()
            else
                print("[AutoChessMode] ⚠️ 定时器: 游戏已启动或模式未激活，跳过启动")
            end
            return nil
        end
    )
end
function AutoChessMode.prototype.onGameStart(self)
    print((("[AutoChessMode] onGameStart called, isActive: " .. tostring(self.isActive)) .. ", isGameActive: ") .. tostring(self.gameState.isGameActive))
    if not self.isActive then
        print("[AutoChessMode] ⚠️ 自走棋模式未激活，跳过游戏开始")
        return
    end
    if self.gameState.isGameActive then
        print("[AutoChessMode] ⚠️ 游戏已经在运行中，跳过重复启动")
        return
    end
    print("[AutoChessMode] ✅ 自动开始游戏...")
    self:startGame()
end
