    local autoDeployTriggered = false
    local countdownTimer = Timers:CreateTimer(
        1,
        function()
            timeLeft = timeLeft - 1
            print(((((("[AutoChessMode] 准备阶段倒计时: " .. tostring(timeLeft)) .. "秒 (stageId: ") .. tostring(stageIdOrNodeId)) .. ", playerId: ") .. tostring(playerId)) .. ")")
            if timeLeft == 3 and not autoDeployTriggered then
