            if timeLeft <= 0 then
                print("[AutoChessMode] ========== 准备阶段结束，开始生成怪物并战斗 ==========")
                print(((("[AutoChessMode] 调用 startBattleWithStage(playerId: " .. tostring(playerId)) .. ", stageId: ") .. tostring(stageIdOrNodeId)) .. ")")
