function AutoChessMode.prototype.handleAugmentSelection(self, playerId, augmentId)
    print((("[AutoChessMode] Player " .. tostring(playerId)) .. " selected augment: ") .. augmentId)
    local augment = HextechAugmentConfig:getAugment(augmentId)
    if not augment then
        Warning("Invalid augment ID: " .. augmentId)
        return
    end
    if self.augmentManager:hasAugment(playerId, augmentId) then
        Warning((("Player " .. tostring(playerId)) .. " already has augment: ") .. augmentId)
        return
    end
    self.augmentManager:addAugment(playerId, augmentId)
    self:syncPlayerAugments(playerId)
    print((("[AutoChessMode] ✅ Augment " .. augmentId) .. " added to player ") .. tostring(playerId))
end
function AutoChessMode.prototype.handleAutoSelectAugment(self, playerId, optionIds)
    if #optionIds == 0 then
        print("[AutoChessMode] No augment options to auto-select for player " .. tostring(playerId))
        return
    end
    local randomIndex = RandomInt(0, #optionIds - 1)
    local selectedId = optionIds[randomIndex + 1]
    print(((((("[AutoChessMode] Auto-selecting augment for player " .. tostring(playerId)) .. ": ") .. selectedId) .. " (from ") .. tostring(#optionIds)) .. " options)")
    self:handleAugmentSelection(playerId, selectedId)
end
