function AutoChessMode.prototype.applyAugmentsToUnit(self, unit, playerId)
    local augmentIds = self.augmentManager:getPlayerAugments(playerId)
    if #augmentIds == 0 then
        return
    end
    print((("[AutoChessMode] Applying " .. tostring(#augmentIds)) .. " augments to unit ") .. unit:GetUnitName())
