            print("[AutoChessMode]   ❌ Failed to add augment: " .. augmentId)
        end
    end
end
function AutoChessMode.prototype.applyMonsterStrength(self, unit, piece, strength)
    print("[AutoChessMode] ========================================")
    print("[AutoChessMode] 💪 应用强度倍率到 " .. unit:GetUnitName())
    local baseHealth = piece.health
    local newMaxHealth = math.floor(baseHealth * strength.healthMultiplier)
    unit:SetBaseMaxHealth(newMaxHealth)
    unit:SetMaxHealth(newMaxHealth)
    unit:SetHealth(newMaxHealth)
    print(((((("[AutoChessMode]    ❤️ 生命值: " .. tostring(baseHealth)) .. " → ") .. tostring(newMaxHealth)) .. " (×") .. __TS__NumberToFixed(strength.healthMultiplier * 100, 0)) .. "%)")
    local baseDamage = piece.damage
    local newDamage = math.floor(baseDamage * strength.damageMultiplier)
    unit:SetBaseDamageMin(newDamage)
    unit:SetBaseDamageMax(newDamage)
    print(((((("[AutoChessMode]    ⚔️ 攻击力: " .. tostring(baseDamage)) .. " → ") .. tostring(newDamage)) .. " (×") .. __TS__NumberToFixed(strength.damageMultiplier * 100, 0)) .. "%)")
    if strength.armorBonus then
        local currentArmor = unit:GetPhysicalArmorValue(false)
        unit:SetPhysicalArmorBaseValue(currentArmor + strength.armorBonus)
        print("[AutoChessMode]    🛡️ 护甲加成: +" .. tostring(strength.armorBonus))
    end
    local finalHealth = unit:GetMaxHealth()
    local finalDamage = unit:GetBaseDamageMin()
    print((("[AutoChessMode]    ✅ 最终属性: HP=" .. tostring(finalHealth)) .. ", DMG=") .. tostring(finalDamage))
    print("[AutoChessMode] ========================================")
end
